        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('records')
    if type(records) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['source_context_channel_unread'])
    names = {'american_employer': 'american_employer_', 'business': 'business_', 'business_trust': 'business_trust_', 'citizenship': 'citizenship_', 'disability': 'disability_', 'international_organization': 'international_organization_', 'itemize_deductions': 'itemize_deductions_', 'medical_institution': 'medical_institution_', 'migration': 'migration_', 'nonresident_alien': 'nonresident_alien_', 'nurses_training_school': 'nurses_training_school_', 'plan': 'plan_', 'retirement': 'retirement_', 'termination': 'termination_', 'unemployment_compensation_agreement': 'unemployment_compensation_agreement_'}
    for index, record in enumerate(records):
        kind = record.get('kind')
        primary = record.get('primary')
        secondary = record.get('secondary')
        participants = record.get('participants')
        beneficiaries = record.get('beneficiaries')
        if not support(witnesses, record, public, True) or kind not in names or type(primary) is not str or type(participants) is not list or type(beneficiaries) is not list or not all(type(x) is str for x in participants + beneficiaries):
            complete = False
            continue
        event = 'source_context_' + kind + '_' + str(index)
        put(facts, names[kind], [event])
        put(facts, 'agent_', [event, primary])
        if kind == 'citizenship':
            if type(secondary) is str:
                put(facts, 'patient_', [event, secondary])
            else:
                complete = False
        elif kind == 'migration':
            if type(secondary) is str:
                put(facts, 'destination_', [event, secondary])
            else:
                complete = False
            if type(record.get('text')) is str:
                put(facts, 'purpose_', [event, record.get('text')])
        elif kind == 'business':
            if type(record.get('text')) is str:
                put(facts, 'type_', [event, record.get('text')])
        elif kind == 'plan':
            if type(record.get('text')) is str:
                put(facts, 'purpose_', [event, record.get('text')])
            for person in beneficiaries:
                put(facts, 'beneficiary_', [event, person])
        elif kind == 'termination':
            if type(secondary) is str:
                service = 'source_context_service_' + str(index)
                put(facts, 'service_', [service])
                put(facts, 'agent_', [service, secondary])
                put(facts, 'patient_', [service, primary])
                put(facts, 'patient_', [event, service])
        elif kind == 'unemployment_compensation_agreement':
            for participant in participants:
                put(facts, 'agent_', [event, participant])
        elif type(secondary) is str:
            put(facts, 'patient_', [event, secondary])
        if type(record.get('start_date')) is str:
            put(facts, 'start_', [event, record.get('start_date')])
        if type(record.get('end_date')) is str:
            put(facts, 'end_', [event, record.get('end_date')])
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

